 if(!this.ground){pitch+=clamp((alpha-trim)*(this.assist?1.05:.24),-.35,.35)*(1-Math.abs(this.controls.pitch));yaw+=clamp(beta*(this.assist?1.65:.8),-.45,.45);if(this.assist&&Math.abs(this.controls.roll)<.06)roll+=clamp(-Math.atan2(r.y,u.y)*.3,-.26,.26);}
