 const stall=clamp((Math.abs(alpha)-.26)/.17,0,1)*(1-hoverBlend);this.stall=stall;const pre=clamp(s.cl0+s.cla*alpha+this.flapsActual*.38,-s.clmax,s.clmax+.18*this.flapsActual);let cl=mix(pre,.9*Math.sin(2*alpha),stall*stall*(3-2*stall));if(forward<0)cl*=.1;const cd=s.cd+s.k*cl*cl+.95*stall*Math.sin(alpha)**2+.023*this.gearActual+.07*this.flapsActual;
 const liftDir=u.subtract(vhat.scale(V.Dot(u,vhat)));if(liftDir.lengthSquared()>.000001)liftDir.normalize();const lift=liftDir.scale(qd*s.area*cl),drag=vhat.scale(-qd*s.area*cd),sideforce=r.scale(-side*Math.abs(side)*rho*s.area*.22);const reverseTaper=this.ground&&this.engine<0?clamp((5+forward)/5,0,1):1;const thrust=this.engine*(s.power?Math.min(s.thrust,s.power/Math.max(speed,24)):s.thrust)*(this.boost?1.65:1)*reverseTaper;// Midpoint rotation makes lift do no numerical work, even at Mach 5.
 const nonLift=drag.add(sideforce).add(f.scale(thrust)).add(u.scale(hoverForce)).scale(1/s.mass).add(new V(0,-9.81,0));
 const turn=V.Cross(vhat,lift.scale(1/s.mass)).scale(dt/(2*speed)),rhs=air.add(V.Cross(turn,air)).add(nonLift.scale(dt));
 this.velocity.copyFrom(rhs.add(V.Cross(turn,rhs)).add(turn.scale(V.Dot(turn,rhs))).scale(1/(1+turn.lengthSquared())));
 const oldY=this.position.y,previous=this.position.clone(),nextSpeed=this.velocity.length(),estimatedY=this.position.y+(air.y+this.velocity.y)*dt*.5,limit=envelopeSpeed(s,estimatedY),limited=governedSpeed(nextSpeed,speed,limit,dt);if(nextSpeed>limited&&nextSpeed>0)this.velocity.scaleInPlace(limited/nextSpeed);
 this.position.addInPlace(air.add(this.velocity).scale(dt*.5));const exactLimit=envelopeSpeed(s,this.position.y),actualSpeed=this.velocity.length();if(actualSpeed>exactLimit)this.velocity.scaleInPlace(exactLimit/actualSpeed);this.distance+=speed*dt;const ground=groundHeight(this.position.x,this.position.z),onWater=ground<0;const clearance=this.gearActual>.8?s.gearHeight:.64,minY=Math.max(0,ground)+clearance;
 if(this.position.y<=minY){const sink=this.velocity.y,bank=Math.abs(r.y),pitchAngle=Math.asin(clamp(f.y,-1,1));if(onWater){this.crash('Water landing. Try approaching the runway with gear and flaps down.',{kind:'water',point:new V(this.position.x,0,this.position.z)});return;}if((sink<-5.8&&this.time>.3)||(this.gearActual<.75&&speed>8)||bank>.3||pitchAngle<-.15||pitchAngle>.52){this.crash('Hard landing. Lower your gear and aim for a gentle descent.',{kind:'terrain',point:new V(this.position.x,ground,this.position.z)});return;}this.position.y=minY;this.velocity.y=Math.max(0,this.velocity.y);this.ground=true;const vf=V.Dot(this.velocity,f),vr=V.Dot(this.velocity,r);this.velocity.subtractInPlace(r.scale(vr*Math.min(1,dt*8)));const brake=input.brake?.48:.018;const loss=Math.min(Math.abs(vf),9.81*brake*dt);this.velocity.subtractInPlace(f.scale(Math.sign(vf)*loss));if(pitchAngle<0){this.q=B.Quaternion.RotationYawPitchRoll(Math.atan2(f.x,f.z),0,0);}if(speed<.5&&Math.abs(this.throttle)<.03&&Math.abs(this.engine)<.03)this.velocity.set(0,0,0);
 }else{this.ground=false;if(this.position.y>minY+.8)this.hadAirborne=true;}this.landed=this.ground&&this.hadAirborne&&this.time>1;
 // Belly, nose, tail and wingtip probes prevent clipping through raised terrain.
 if(!this.ground)for(const probe of[[0,-.55,s.noseLength||2.8],[0,0,-(s.tailLength||4.3)],[-s.span*.48,.5,0],[s.span*.48,.5,0]]){const pt=this.position.add(r.scale(probe[0])).add(u.scale(probe[1])).add(f.scale(probe[2]));if(pt.y<Math.max(0,groundHeight(pt.x,pt.z))){const h=groundHeight(pt.x,pt.z);this.crash('Terrain strike. Give your wingtips and tail more clearance.',{kind:h<0?'water':'terrain',point:new V(pt.x,Math.max(0,h),pt.z)});return;}}
 const probes=[new V(0,-.4,0),f.scale(s.noseLength||3.8),f.scale(-(s.tailLength||4)),r.scale(s.span*.25),r.scale(-s.span*.25),r.scale(s.span*.47),r.scale(-s.span*.47)];
 let nearest=null;for(const c of colliders){if(this.position.y>c.y+9||Math.abs(this.position.x-c.x)>c.w/2+s.span||Math.abs(this.position.z-c.z)>c.d/2+12)continue;for(const off of probes){const hit=segmentBox(previous.add(off),this.position.add(off),c,1);if(hit&&(!nearest||hit.t<nearest.t))nearest={...hit,target:c};}}
